    },
    {
      "audio_path": null,
      "back": {
        "confusion": {
          "vi": "Tiếng Việt có thể bỏ \"là\" (Tôi sinh viên), nhưng tiếng Anh không bao giờ được bỏ be trong câu kiểu này."
        },
        "examples": [
          {
            "target": "I am a student.",
            "translation": {
              "vi": "Tôi là sinh viên."
            }
