    {
      "audio_path": null,
      "back": {
        "confusion": {
          "vi": "Call me, không nói call to me - tiếng Việt \"gọi cho tôi\" có chữ \"cho\", nhưng tiếng Anh không cần giới từ."
        },
        "examples": [
          {
            "target": "Please call me tonight.",
            "translation": {
              "vi": "Tối nay gọi cho mình nhé."
            }
          }
        ],
        "meaning": {
          "vi": "gọi điện (cho ai)"
