      ],
      "source_id": "bf7e159d-73d5-5f79-89cd-f97fb0d667f8",
      "status": "published"
    },
    {
      "audio_path": null,
      "back": {
        "confusion": {
          "vi": "Confirm đi thẳng với tân ngữ - confirm the time, không nói \"confirm about the time\"."
        },
        "examples": [
          {
            "target": "Could you confirm the time of the interview?",
            "translation": {
              "vi": "Anh/chị xác nhận giúp tôi giờ phỏng vấn được không?"
            }
          }
        ],
        "meaning": {
          "vi": "xác nhận"
