    {
      "audio_path": null,
      "back": {
        "confusion": {
          "vi": "Day là ngày nói chung hoặc thứ trong tuần (What day is it?); ngày tháng cụ thể như 5/6 gọi là date."
        },
        "examples": [
          {
            "target": "There are seven days in a week.",
            "translation": {
              "vi": "Một tuần có bảy ngày."
            }
          }
        ],
        "meaning": {
          "vi": "ngày; ban ngày"
        }
      },
      "content_hash": "4809b0de98dd36a4ea784995c3ebaee9aea8552d35cc679efb2852c3a3263ea8",
