      "status": "published"
    },
    {
      "audio_path": null,
      "back": {
        "confusion": {
          "vi": "Giống probably, definitely đứng sau will và trước won't - I definitely won't be late."
        },
        "examples": [
          {
            "target": "I'll definitely call you when I arrive.",
            "translation": {
              "vi": "Khi đến nơi tôi chắc chắn sẽ gọi cho bạn."
            }
          }
        ],
        "meaning": {
          "vi": "chắc chắn"
        }
      },
      "content_hash": "8157009f24e4c6c48333595106b0fb9fd473a0cd2bec9bc4217b79fa53308a9f",
