      "status": "published"
    },
    {
      "audio_path": null,
      "back": {
        "confusion": {
          "vi": "Anh-Anh viết động từ là practise, danh từ là practice; Anh-Mỹ viết practice cho cả hai. Sau practise dùng V-ing - practise speaking."
        },
        "examples": [
          {
            "target": "I've been practising the guitar every evening.",
            "translation": {
              "vi": "Tối nào mình cũng tập đàn guitar."
            }
          }
        ],
        "meaning": {
          "vi": "luyện tập"
        }
      },
      "content_hash": "2527dc4018a8789bc2db98841e314e1603bb5df91b753846fafa334b1b20e1e4",
      "difficulty": 2,
      "front": {
        "ipa": "/ˈpræktɪs/",
        "pos": "động từ",
        "text": "practise (UK) / practice (US)"
      },
      "id": "83d13517-fa90-56c1-b011-796c607a5695",
      "is_demo": true,
