      "skill_tags": [
        "grammar"
      ],
      "source_id": "bf7e159d-73d5-5f79-89cd-f97fb0d667f8",
      "status": "published"
    },
    {
      "audio_path": null,
      "back": {
        "examples": [
          {
            "target": "Here's your prescription. You can get the medicine at the pharmacy.",
            "translation": {
              "vi": "Đây là đơn thuốc của bạn. Bạn có thể mua thuốc ở hiệu thuốc."
            }
          }
        ],
        "meaning": {
          "vi": "đơn thuốc"
        },
        "pronunciation_note": {
          "vi": "Nhấn âm giữa \"pri-XKRÍP-sần\"; cụm scr đọc liền, không chèn nguyên âm."
        }
      },
      "content_hash": "770d7697ffb63b0c112d08bb600c3c1df64047408cf765ddaeb9b07d7e60c012",
      "difficulty": 3,
      "front": {
