      ],
      "source_id": "bf7e159d-73d5-5f79-89cd-f97fb0d667f8",
      "status": "published"
    },
    {
      "audio_path": null,
      "back": {
        "confusion": {
          "vi": "Report something to someone (báo cho ai), không nói report someone something. Phóng viên là reporter."
        },
        "examples": [
          {
            "target": "The newspaper reported that two people were injured.",
            "translation": {
              "vi": "Tờ báo đưa tin rằng có hai người bị thương."
            }
          }
        ],
        "meaning": {
          "vi": "bản tin, bản báo cáo; đưa tin, báo cáo"
        },
        "pronunciation_note": {
          "vi": "Nhấn vào âm thứ hai PORT, cả khi là danh từ lẫn động từ."
        }
      },
      "content_hash": "559d3348cc3a5d4c269e83fd7a60c919ff884255dfd28dd63e829678d9543453",
      "difficulty": 3,
      "front": {
        "ipa": "UK /rɪˈpɔːt/ · US /rɪˈpɔːrt/",
        "pos": "danh từ, động từ",
        "text": "report"
      },
      "id": "4511e647-b785-56db-ab1d-ced0d2fd5bef",
      "is_demo": true,
      "item_type": "vocab",
      "key": "en:item:report",
