      "skill_tags": [
        "grammar"
      ],
      "source_id": "bf7e159d-73d5-5f79-89cd-f97fb0d667f8",
      "status": "published"
    },
    {
      "audio_path": null,
      "back": {
        "confusion": {
          "vi": "It hoặc them đứng giữa try và on - try it on, không nói try on it. Với shoes, jeans dùng them vì là số nhiều."
        },
        "examples": [
          {
            "target": "I like this dress. Can I try it on?",
            "translation": {
              "vi": "Mình thích cái đầm này. Mình mặc thử được không?"
            }
          },
          {
            "target": "Can I try them on?",
            "translation": {
              "vi": "Mình thử đôi này / cái quần này được không?"
            }
          }
        ],
        "meaning": {
          "vi": "Tôi mặc thử được không?"
        },
        "pronunciation_note": {
          "vi": "Ba từ nối liền \"trai-i-TON\", nhấn vào on."
        }
      },
      "content_hash": "c79ddb1fd3fa8fa27a0beb557f903c178e70a7f2ce60b506eac9c8f432522652",
      "difficulty": 2,
      "front": {
