    {
      "audio_path": null,
      "back": {
        "confusion": {
          "vi": "Hai người sinh đôi là twins (số nhiều). Một người là a twin brother hoặc a twin sister."
        },
        "examples": [
          {
            "target": "Mai and Hoa are twins.",
            "translation": {
              "vi": "Mai và Hoa là chị em sinh đôi."
            }
          },
          {
            "target": "I've got a twin brother.",
            "translation": {
              "vi": "Tôi có một anh (em) trai sinh đôi."
            }
          }
        ],
        "meaning": {
          "vi": "anh/chị/em sinh đôi"
        }
      },
      "content_hash": "ddc8791cc860b9527dff8d1f318c4a04959f63d32623e47e46b6099079a62da4",
