      "skill_tags": [
        "grammar"
      ],
      "source_id": "bf7e159d-73d5-5f79-89cd-f97fb0d667f8",
      "status": "published"
    },
    {
      "audio_path": null,
      "back": {
        "confusion": {
          "vi": "Không viết 아프어요 hay 아퍼요; dạng đúng duy nhất là 아파요."
        },
        "examples": [
          {
            "target": "머리가 아파요.",
            "translation": {
              "vi": "Tôi đau đầu."
            }
          },
          {
            "target": "요즘 너무 바빠요.",
            "translation": {
              "vi": "Dạo này tôi bận quá."
            }
          }
        ],
        "meaning": {
          "vi": "Thân kết thúc bằng ㅡ thì ㅡ rơi mất trước -아/어. Nhìn nguyên âm của âm tiết đứng trước - ㅏ/ㅗ thì thêm 아 (아프다 → 아파요, 바쁘다 → 바빠요), còn lại thêm 어 (예쁘다 → 예뻐요); thân một âm tiết thêm 어 (쓰다 → 써요)."
        }
      },
      "content_hash": "a431729ee35d0983c9f661817886c8592916ea80b1d0b258e5d56f3a785e981e",
      "difficulty": 3,
      "front": {
        "pos": "chia động từ",
        "romanization": "eu tallak",
        "text": "Bất quy tắc ㅡ (아프다 → 아파요)"
      },
      "id": "82e28ea7-ea24-58ec-aaa3-bb9456beac32",
      "is_demo": true,
      "item_type": "grammar_point",
      "key": "ko:item:gram-eu-irregular",
      "language_code": "ko",
      "level_code": "topik2",
      "reviewed_at": null,
